char *my_memmem (char *haystack, size_t haystacklen, /* <=== my_memmem:char*(char*,ANY,char*,ANY) */ 
	      char *needle, size_t needlelen)
{
  char *c;
  for (c = haystack; c <= haystack + haystacklen - needlelen; c++)
    if (!memcmp (c, needle, needlelen))
      return c;
  return 0;
}

char *my_strcasestr (char *haystack, const char *needle) /* <=== my_strcasestr:char*(char*,char*) */ 
{
  char *c;
  for (c = haystack; *c; c++)
    if (!strncasecmp(c, needle, strlen(needle)))
      return c;
  return 0;
}

ushort CLASS sget2 (uchar *s) /* <=== LibRaw.sget2:unsigned shortint(unsigned char*) */ 
{
  if (order == 0x4949)		/* "II" means little-endian */
    return s[0] | s[1] << 8;
  else				/* "MM" means big-endian */
    return s[0] << 8 | s[1];
}

static ushort saneSonyCameraInfo(uchar a, uchar b, uchar c, uchar d, uchar e, uchar f){ /* <=== saneSonyCameraInfo:unsigned shortint(unsigned char,unsigned char,unsigned char,unsigned char,unsigned char,unsigned char) */ 
	if ((a >> 4) > 9) return 0;
	else if ((a & 0x0f) > 9) return 0;
	else if ((b >> 4) > 9) return 0;
	else if ((b & 0x0f) > 9) return 0;
	else if ((c >> 4) > 9) return 0;
	else if ((c & 0x0f) > 9) return 0;
	else if ((d >> 4) > 9) return 0;
	else if ((d & 0x0f) > 9) return 0;
	else if ((e >> 4) > 9) return 0;
	else if ((e & 0x0f) > 9) return 0;
	else if ((f >> 4) > 9) return 0;
	else if ((f & 0x0f) > 9) return 0;
return 1;
}

static ushort bcd2dec(uchar data){ /* <=== bcd2dec:unsigned shortint(unsigned char) */ 
	if ((data >> 4) > 9) return 0;
	else if ((data & 0x0f) > 9) return 0;
	else return (data >> 4) * 10 + (data & 0x0f);
}

ushort CLASS sget2Rev(uchar *s)	// specific to some Canon Makernotes fields, where they have endian in reverse /* <=== LibRaw.sget2Rev:unsigned shortint(unsigned char*) */ 
{
	if (order == 0x4d4d)		/* "II" means little-endian, and we reverse to "MM" - big endian */
		return s[0] | s[1] << 8;
	else						/* "MM" means big-endian... */
		return s[0] << 8 | s[1];
}

ushort CLASS get2() /* <=== LibRaw.get2:unsigned shortint() */ 
{
  uchar str[2] = { 0xff,0xff };
  fread (str, 1, 2, ifp);
  return sget2(str);
}

unsigned CLASS sget4 (uchar *s) /* <=== LibRaw.sget4:unsigned int(unsigned char*) */ 
{
  if (order == 0x4949)
    return s[0] | s[1] << 8 | s[2] << 16 | s[3] << 24;
  else
    return s[0] << 24 | s[1] << 16 | s[2] << 8 | s[3];
}

unsigned CLASS get4() /* <=== LibRaw.get4:unsigned int() */ 
{
  uchar str[4] = { 0xff,0xff,0xff,0xff };
  fread (str, 1, 4, ifp);
  return sget4(str);
}

unsigned CLASS getint (int type) /* <=== LibRaw.getint:unsigned int(int) */ 
{
