float CLASS int_to_float (int i) /* <=== LibRaw.int_to_float:float(int) */ 
{
  union { int i; float f; } u;
  u.i = i;
  return u.f;
}

double CLASS getreal (int type) /* <=== LibRaw.getreal:double(int) */ 
{
  union { char c[8]; double d; } u,v;
  int i, rev;

  switch (type) {
    case 3: return (unsigned short) get2();
    case 4: return (unsigned int) get4();
    case 5:
      u.d = (unsigned int) get4();
      v.d = (unsigned int)get4();
      return u.d / (v.d ? v.d : 1);
    case 8: return (signed short) get2();
    case 9: return (signed int) get4();
    case 10:
      u.d = (signed int) get4();
      v.d = (signed int)get4();
      return u.d / (v.d?v.d:1);
    case 11: return int_to_float (get4());
    case 12:
      rev = 7 * ((order == 0x4949) == (ntohs(0x1234) == 0x1234));
      for (i=0; i < 8; i++)
	u.c[i ^ rev] = fgetc(ifp);
      return u.d;
    default: return fgetc(ifp);
  }
}

